function CheckoutProvider({ children }) {
  const [state, dispatch] = useReducer(checkoutReducer, initial);
  return (
    <CheckoutDispatchContext.Provider value={dispatch}>
      <CheckoutStateContext.Provider value={state}>
        {children}
      </CheckoutStateContext.Provider>
    </CheckoutDispatchContext.Provider>
  );
}

function AddButton() {
  const dispatch = useContext(CheckoutDispatchContext);
  return <button onClick={() => dispatch({ type: "item-added" })}>Add</button>;
}

function TotalDisplay() {
  const { total } = useContext(CheckoutStateContext);
  return <strong>{total}</strong>;
}

