function checkoutReducer(state, action) {
  switch (action.type) {
    case "order-submitted": {
      api.submitOrder(state.items); // POST fired from here
      return { ...state, status: "submitting" };
    }
  }
}

Logs (dev, StrictMode): one dispatch -> two POST /orders requests.
The reducer must be ___b1___: React runs it during rendering and may invoke it ___b2___ times for one dispatch. The network call belongs in the ___b3___ (or an effect), which then dispatches a result action.

